  document.querySelectorAll('.web-banner').forEach(function(el){ el.style.display='none'; });
  document.querySelectorAll('.mobile-banner').forEach(function(el){ el.style.display='none'; });
  document.querySelectorAll('.desktop-slider').forEach(function(el){ el.style.display='none'; });
  document.querySelectorAll('[class*="md-side-banner"]').forEach(function(el){ el.style.display='none'; });
  console.log('[AML] Done. isPASA:' + isPASA + ' | Cards:' + CARDS.length + ' | Banners:' + bannerEls.length);
